def asset(row):
    a={
      "asset_id":row["id"],"version":"1.0.0","schema_version":"1.0.0","subject":"PHYSICS","lifecycle_status":"CANDIDATE",
      "capability_refs":row["caps"],
      "applicability_conditions":["use when this capability is required by the P-F LearnerStudyModel","use for source-grounded Grade-9 Physics teaching rather than formula recall alone"],
      "physical_anchor":row["anchor"],
      "system_frame_setup":{"system_definition":"Name the physical system before calculation.","frame_rule":"Use the frame required by the bound P-F/P-D source obligations.","sign_rule":"Declare and preserve the sign convention before interpreting signed states."},
      "representation_path":row["reps"],
      "ordinary_language_bridge":row["bridge"],
      "model_validity_cue":row["validity"],
      "relation_reconstruction_route":row["reconstruct"],
      "minimal_contrast":{"shared_structure":"Hold the target mechanism fixed while changing only the decisive feature.","wrong_case":row["wrong"][0],"correct_case":row["contrast"],"prediction_prompt":"Predict which description is physically consistent before calculating.","decisive_feature":row["contrast"]},
      "worked_example_family":"BOUND_FROM_STUDY_SCOPE",
      "common_wrong_model":row["wrong"],
      "misconception_discriminator":{"probe":"Present the minimal contrast and require a physical explanation before algebra.","decisive_response":"Learner identifies the decisive physical feature and rejects the wrong model."},
      "repair_route":["return to the physical anchor and representation before equations","contrast the plausible wrong model with the correct model","retry on a new problem-family instance","transfer without the original scaffold"],
      "verification_method":["check units/dimensions and sign/direction where applicable","check magnitude, continuity, limiting behavior and model consistency where applicable"],
      "fading_dimensions":["physical anchor supplied","representation supplied","reconstruction cue supplied","verification cue supplied"],
      "transfer_family":row["transfer"],
      "known_limitations":["applies only under the stated model-validity conditions","does not replace a different P-D problem family when the physical mechanism changes"],
      "equation_features_to_explain":row.get("eq",[]),
      "graph_semantics_required":bool(row.get("graph",False)),
      "state_handoff_required":bool(row.get("handoff",False)),
      "provenance":{"evidence_class":"REPOSITORY_AUTHORITY_PLUS_AI_ASSISTED_DRAFT","source_refs":BASE_SOURCE_REFS,"authoring_origin":"AI_ASSISTED_DRAFT"},
      "review":{"required_dimensions":["SUBJECT","PEDAGOGY"],"status":"PENDING_HUMAN_REVIEW","human_review_evidence_refs":[]},
      "asset_digest":""
    }
    a["asset_digest"]=digest(a,"asset_digest")
    return a

def get_registry():
    r={"registry_id":"PHY-PCK-CANDIDATE-REGISTRY-v1","schema_version":"1.0.0","subject":"PHYSICS","registry_class":"CANDIDATE","asset_documents":[asset(x) for x in ROWS],"registry_digest":""}
    r["registry_digest"]=digest(r,"registry_digest")
    return r

def main():
    ap=argparse.ArgumentParser(); ap.add_argument("--out")
    a=ap.parse_args(); r=get_registry()
    text=json.dumps(r,ensure_ascii=False,indent=2,sort_keys=True)+"\n"
    if a.out: Path(a.out).write_text(text,encoding="utf-8")
    else: print(text,end="")
if __name__=="__main__": main()
